\label{thm_no_rigidity}
    For every $n\geqslant 2$, there exists $S\subseteq{\mathbb{H}}^n$ satisfying the following properties.     
    \begin{enumerate}
        \item $S$ is a smooth, connected, embedded, two-sided, complete hypersurface without boundary;
        \item $S$ is non-characteristic;
        \item $S$ is the boundary of a global perimeter minimizer. In particular, $S$ is minimal, stable and satisfies the area growth conditions \eqref{updesubintro} for every $p\in S$.
        \item $S$ is an entire, smooth intrinsic graph along $X_1$;
        \item $S$ is not a vertical hyperplane;
        \item $S$ does not verify any of \eqref{eq:P1}, \eqref{eq:P2}, \eqref{eq:P3}.
    \end{enumerate}

\label{thm_main_1}
For every $n\geqslant 2$, there exists $u\in C^\infty({\mathbb{R}}^n)$ such that
\begin{equation}\label{eq:target}
 \operatorname{div}\left(\frac{Du}{\sqrt{|Du|^2+4|x|^2}}\right)=0,
 \qquad \frac{\partial u}{\partial x_1}\geqslant 1\qquad\text{on }{\mathbb{R}}^n.
\end{equation}
Moreover, $u$ is odd in $x_1$ and invariant under orthogonal transformations of $x_2,\ldots,x_n$.

\label{propcriteriointrinsic}
Let $G\in C^\infty({\mathbb{H}}^n)$, and set 
$S=\{G=0\}$. If $X_1G\geqslant 1$ on ${\mathbb{H}}^n$, then $S$ is an entire, smooth intrinsic graph along $X_1$.

\label{propositiondiriboundcondex}
Let $R,K>0$ and $\varepsilon\in(0,1]$. The problem
\begin{equation}\label{eq_diri_ball_eps}
 \mathcal Q^\varepsilon u=0\quad\text{on }B_R,
 \qquad u=Kx_1\quad\text{on }\partial B_R
\end{equation}
has a unique solution $u\in C^\infty(\overline B_R)$. Moreover, $u$ is odd in $x_1$, and invariant under orthogonal transformations of $x_2,\ldots,x_n$.

First, we show existence. We rely on the well-known Leray-Schauder fixed point approach. To this aim, 
    Fix any $\alpha\in(0,1)$. By \cite[Theorem 13.8]{MR1814364}, \eqref{eq_diri_ball_eps} is solvable in $C^{2,\alpha}(\overline B_R)$ provided that solutions to 
    \begin{equation}\label{eq_diri_ball_eps_sigma}
 \mathcal N^{\varepsilon,\sigma} u=0\quad\text{on }B_R,
 \qquad u=\sigma Kx_1\quad\text{on }\partial B_R
\end{equation}
are bounded in $C^1(\overline B_R)$ uniformly in $u$ and $\sigma\in[0,1]$. Fix any such solution. When $\sigma=0$, then $u\equiv 0$ solves \eqref{eq_diri_ball_eps_sigma}, and it is the unique solution by \Cref{prop_comparison_principle}. Therefore, we assume that $\sigma> 0$. 

\smallskip
\noindent \textbf{Step 1.} We first show that $u\in C^\infty(\overline B_R)$. Indeed, setting $\mathcal A^\varepsilon(x)=A^\varepsilon(x,Du(x))$, then $u$ satisfies 
\begin{equation}\label{linear_elliptic_forreg}
\sum_{i,j=1}^n\mathcal A^\varepsilon(x)_{ij}D^2 u_{ij}-4\sigma \langle Du,x\rangle=0\qquad \text{on $B_R$.}
\end{equation}
The latter, is a second-order \emph{linear} equation without zero-order terms. Since $u\in C^{2,\alpha}(\overline B_R)$, then \eqref{eigenvaluesofaeps} implies that \eqref{linear_elliptic_forreg} is uniformly elliptic, and that $\mathcal A^\varepsilon_{ij}\in C^{1,\alpha}(\overline B_R)$. Therefore, \cite[Theorem 6.19]{MR1814364} grants $u\in C^{3,\alpha}(\overline B_R)$. Bootstrapping the above argument, $u\in C^\infty(\overline B_R).$

\smallskip
\noindent \textbf{Step 2.} Next, we derive uniform estimates in $C^1(\overline B_R)$. First, notice that the constant functions $-KR$ and $KR$ are solutions to the equation. Moreover, $-KR\leqslant u\leqslant KR$ on $\partial B_R.$ Then, \Cref{prop_comparison_principle} yields $-KR\leqslant u\leqslant KR$ on $\overline B_R$, i.e. $|u|\leqslant KR$ on $\overline B_R$. 

\smallskip
\noindent \textbf{Step 3.} In order to achieve boundary gradient estimates, we exhibit an upper and a lower barrier realizing the boundary datum. Accordingly, set $b_\pm\coloneqq \sigma Kx_1\pm(R^2-|x|^2)$. Clearly, $b_+=b_-=u$ on $\partial B_R$. We show that $\mathcal N^{\varepsilon,\sigma} b_+\leqslant 0$. Indeed, since
\begin{equation*}
    Db_+=(\sigma K-2x_1,-2x_2,\ldots,-2x_n),\quad Db_-=(\sigma K+2x_1,2x_2,\ldots,2x_n),\quad D^2 b_+=-2I_n,\quad D^2 b_-= 2I_n,
\end{equation*}
then 
\begin{equation*}
    \begin{split}
        \mathcal N^{\varepsilon,\sigma} b_+\overset{\eqref{definizione_matrici_eqregeps}}&{=}-2n\big(|Db_+|^2+4|x|^2+\varepsilon^2\big)+2|Db_+|^2-4\sigma\langle D b_+,x\rangle \\
        &=-2(n-1)|Db_+|^2-4\sigma\langle D b_+,x\rangle-8n|x|^2-2n\varepsilon^2\\
        &=-2(n-1)\left|Db_++\frac{\sigma x}{n-1}\right|^2+\left(\frac{2\sigma^2}{n-1}-8n\right)|x|^2-2n\varepsilon^2\\
        &\leqslant 0.
    \end{split}
\end{equation*}
Similarly,
\begin{equation*}
    \begin{split}
         \mathcal N^{\varepsilon,\sigma} b_-\overset{\eqref{definizione_matrici_eqregeps}}&{=}2n\big(|Db_-|^2+4|x|^2+\varepsilon^2\big)-2|Db_-|^2-4\sigma\langle D b_-,x\rangle \\
        &=2(n-1)|Db_-|^2-4\sigma\langle D b_-,x\rangle+8n|x|^2+2n\varepsilon^2\\
        &=2(n-1)\left|Db_--\frac{\sigma x}{n-1}\right|^2+\left(8n-\frac{2\sigma^2}{n-1}\right)|x|^2+2n\varepsilon^2\\
        &\geqslant 0.
    \end{split}
\end{equation*}
Therefore, \Cref{prop_comparison_principle} yields $b_- \leqslant u\leqslant b_+$ on $\overline B_R$. Since both barriers coincide with $u$ on $\partial B_R$ and $|D b_\pm|\leqslant K+2R$ on $\overline B_R$, we conclude that $|D u|\leqslant K+2R$ on $\partial B_R$. 

\smallskip
\noindent \textbf{Step 4.} 
To conclude, we show that 
\begin{equation}\label{quasi_max_principle}
    \max_{\overline B_R} |Du|^2\leqslant \max\left\{ \max_{\partial B_R} |Du|^2,4R^2\right\}.
\end{equation}
By contradiction, assume \eqref{quasi_max_principle} does not hold. Let $\tilde x\in B_R$ be a point where \eqref{quasi_max_principle} fails. Then, we may assume that $\tilde x$ is an interior maximum point of $w$. For notational simplicity, set $w=|Du|^2$. Therefore
\begin{equation}\label{maximum_point_of_w_in_max_principle}
    Dw=2 D^2 u\,Du=2\left(\sum_{i=1}^n u_{1i} u_i,\ldots,\sum_{i=1}^n u_{ni} u_i\right)=0,\qquad D^2 w\leqslant 0\qquad\text{at $\tilde x$.}
\end{equation}
In particular, 
\begin{equation}\label{equazione_in_pt_massimo_w_max_principle_34578}
(w+4|x|^2+\varepsilon^2)\Delta u\overset{\eqref{eq_diri_ball_eps_sigma}}{=}4\sigma \langle Du,x\rangle\qquad\text{at $\tilde x$.}
\end{equation}
By direct computation, at $\tilde x$,
\begin{equation}\label{eq_ausiliarie_28486948375}
    \partial _i\langle Du,x\rangle =u_i+\sum_{j=1}^nu_{ij} x_j,\qquad \partial _i A^\varepsilon_{jk}\coloneqq \partial_i\left(A^\varepsilon_{jk}(x,Du)\right)\overset{\eqref{maximum_point_of_w_in_max_principle}}{=}8x_i\delta_{jk}-u_{ij}u_k-u_{ik}u_j\qquad i=1,\ldots, n.
\end{equation}

Therefore, at $\tilde x$,
\begin{equation*}
    \begin{split}
        0\overset{\eqref{eq_diri_ball_eps_sigma}}&{=}\sum_{i=1}^n\partial_i\left(\mathcal N^{\varepsilon,\sigma} u\right)\,u_i\\
        \overset{\eqref{maximum_point_of_w_in_max_principle},\eqref{eq_ausiliarie_28486948375}}&{=}\sum_{i,j,k=1}^n\partial_iA^\varepsilon_{jk}\,u_{jk}\,u_i+\sum_{i,j,k=1}^nA^\varepsilon_{jk}\,u_{ijk}\,u_i-4\sigma w\\
        \overset{\eqref{maximum_point_of_w_in_max_principle},\eqref{eq_ausiliarie_28486948375}}&{=}8\Delta u\langle Du,x\rangle+\sum_{i,j,k=1}^nA^\varepsilon_{jk}\,u_{ijk}\,u_i-4\sigma w,
    \end{split}
\end{equation*}
whence
\begin{equation}\label{eq_ausiliariaperderivataaaaaa384954}
    \sum_{i,j,k=1}^nA^\varepsilon_{jk}\,u_{ijk}\,u_i=4\sigma w-8\Delta u\langle Du,x\rangle\qquad\text{at $\tilde x$.}
\end{equation}
Noticing that $\operatorname{trace}\left(A^\varepsilon\cdot D^2 w\right)\leqslant 0$ at $\tilde x$ by \eqref{maximum_point_of_w_in_max_principle}, then, at $\tilde x$,  
\begin{equation*}
\begin{split}
      0&\geqslant \frac{1}{2}\sum_{i,j=1}^nA^\varepsilon_{ij}w_{ij}\\
      &=\sum_{i,j,k=1}^nA^\varepsilon_{ij}\partial_i\big(u_{jk} u_k\big)\\
      &=\sum_{i,j,k=1}^nA^\varepsilon_{ij}u_{ijk} u_k+\sum_{i,j,k=1}^nA^\varepsilon_{ij}u_{jk} u_{ik}\\
      \overset{\eqref{eq_ausiliariaperderivataaaaaa384954}}&{=}4\sigma w-8\Delta u\langle Du,x\rangle+\sum_{i,j,k=1}^nA^\varepsilon_{ij}u_{jk} u_{ik}\\
      \overset{\eqref{maximum_point_of_w_in_max_principle}}&{=}4\sigma w-8\Delta u\langle Du,x\rangle+(w+4|x|^2+\varepsilon)^2|D^2 u|^2.
\end{split}   
\end{equation*}
In particular, $4\sigma w-8\Delta u\langle Du,x\rangle\leqslant 0$ at $\tilde x$. On the other hand, at $\tilde x$,
\begin{equation*}
    \begin{split}
        4\sigma w-8\Delta u\langle Du,x\rangle\overset{\eqref{equazione_in_pt_massimo_w_max_principle_34578}}&{=}4\sigma \left(w-\frac{8\langle Du,x\rangle^2}{w+4|x|^2+\varepsilon^2}\right)\\
        &\geqslant 4\sigma w\left(1-\frac{8|x|^2}{w+4|x|^2+\varepsilon^2}\right)\\
        &=4\sigma w\left(\frac{w-4|x|^2+\varepsilon^2}{w+4|x|^2+\varepsilon^2}\right),
    \end{split}
\end{equation*}
Since $\sigma> 0$ and $w(\tilde x)> 4R^2$ by the choice of $\tilde x$, then   $4\sigma w-8\Delta u\langle Du,x\rangle> 0$ at $\tilde x$, a contradiction. Therefore \eqref{quasi_max_principle} holds. Combining the previous step, we conclude that \eqref{eq_diri_ball_eps} is solvable in $C^{2,\alpha}(\overline B_R)$.

\smallskip
\noindent \textbf{Step 5.} Let $u\in C^{2,\alpha}(\overline B_R)$ solve \eqref{eq_diri_ball_eps}. By Step 1, $u\in C^{\infty}(\overline B_R)$. Moreover, $u$ is unique by \Cref{prop_comparison_principle}. Since $x\mapsto -u(-x_1,x_2,\ldots,x_n)$ solves  \eqref{eq_diri_ball_eps} as well, then $u$ is odd in $x_1$ by uniqueness. Similarly, it is simple to check that $x\mapsto u(x_1, R(x_2,\ldots,x_n))$ solves \eqref{eq_diri_ball_eps} for any orthogonal transformation $R$ of $x_2,\ldots,x_n$. Again, the thesis follows by uniqueness.

\label{quasimaximumprincipleproposition}
    Let $0< \varrho\leqslant R$, $\varepsilon\in (0,1]$. Let $u\in C^\infty(\overline B_R)$ satisfy $\mathcal Q^\varepsilon u=0$ on $B_R$. Then  
\begin{equation}\label{quasi_max_principle_in_proposition}
    \max_{\overline B_\varrho} |Du|^2\leqslant \max\left\{ \max_{\partial B_\varrho} |Du|^2,4\varrho^2\right\}.
\end{equation}

\label{propunistimamain3948573883derivata}
For every $R>0$ and $\varepsilon\in(0,1]$,
the solution $u\in C^\infty(\overline B_R)$ of \eqref{eq_diri_ball_eps}
with $K=K(R)$ as in \eqref{definizionekappaperheightestimates3948568}
satisfies
\begin{equation}\label{uniformestimatesproprincheigh}
 x_1\leqslant u(x)\leqslant 2(4^\gamma C_n)^{\frac{1}{1-2\gamma}} x_1(1+|x|^2)^\gamma
 \qquad\text{on }\overline B_R\cap\{x_1\geqslant0\}.
\end{equation}

\label{prop:barrier-profile}
Let $h:{\mathbb{R}}_+\to{\mathbb{R}}$ be a smooth function. Set $v(x)=x_1h(|x|^2)$. Then 
\begin{equation}\label{eq:barrier-profile}
 \frac{\mathcal N^\varepsilon v}{x_1}=C^\varepsilon(|x|^2)+x_1^2D(|x|^2),\qquad
 \frac{\Delta v}{x_1}=2(n+2)h'+4|x|^2 h''\qquad\text{on } \{x_1> 0\},
\end{equation}
where
\begin{align*}
 C^\varepsilon(s)&\coloneqq 4s(h^2+4s+\varepsilon^2)h''
       +[2(n-1)h^2+8(n+1)s+2(n+2)\varepsilon^2]h'
       -8s h(h')^2-4h,\\
 D(s)&\coloneqq 8nh(h')^2+8(n-1)s(h')^3-4h^2h''.
\end{align*}
In particular, if $h>0$, $h'>0$ and $h''<0$, then $D>0$ and 
\begin{equation}
\label{eq:cepsin}
C^\varepsilon<\frac{\mathcal N^\varepsilon v}{x_1}  \leqslant C^\varepsilon+sD
\end{equation}
where
\begin{equation}\label{eq:barrier-endpoint}
 \begin{split}
 C^\varepsilon+sD={}&4s(4s+\varepsilon^2)h''
       +[8(n+1)s+2(n+2)\varepsilon^2]h'-4h+2(n-1)(h+2s h')^2h'.
 \end{split}
\end{equation}

\label{prop:barrier-upper}
For every $n\geqslant2$ and for every $\varepsilon\in(0,1]$, the smooth function
\[
 U(x)\coloneqq x_1\left[1+\left(1+\frac{|x|^2}{4}\right)^\gamma\right]
\]
satisfies
\begin{equation}\label{eq:barrier-upper}
 \mathcal N^\varepsilon U\leqslant 0,\qquad
 4^{-\gamma}x_1(1+|x|^2)^\gamma
 \leqslant U(x)\leqslant2x_1(1+|x|^2)^\gamma\qquad \text{on $\{x_1>0\}$.}
\end{equation}

\label{prop:barrier-lower-higher}
For every $n\geqslant3$ and for every $\varepsilon\in(0,1]$, the smooth function
\[
 u_-(x)\coloneqq x_1h(|x|^2),\qquad
 h(s)\coloneqq1+\frac{(1+2s)^\gamma-1}{2\gamma}
\]
satisfies
\begin{equation}\label{eq:barrier-lower-higher}
 \mathcal N^\varepsilon u_-\geqslant 0,\qquad
 x_1\leqslant u_-(x)\leqslant\frac{2^\gamma}{2\gamma}x_1(1+|x|^2)^\gamma\qquad\text{on }\{x_1> 0\}.
\end{equation}

\label{prop:barrier-lower-planar}
Let $n=2$ and $\delta=3\gamma-2$. For every $\varepsilon\in(0,1]$, the smooth function
\[
 u_-(x)=x_1(1+8|x|^2)^\gamma+3x_1^3(1+8|x|^2)^\delta
\]
satisfies
\begin{equation}\label{subsoluzionejernfvojnttijvnrtvjnr}
   \mathcal N^\varepsilon u_-\geqslant 0,\qquad x_1\leqslant u_-\leqslant 3x_1(1+|x|^2)^\gamma,  \qquad \text{on }\{x_1> 0\}.
\end{equation}

\label{thm_uniform_gradient}
Let $0<\varrho_1<\varrho_2< R$.   Let $u\in C^\infty(\overline B_R)$ satisfy $\mathcal Q^\varepsilon u=0$ on $B_R$.
Let $r,\gamma_1> 0$ and $\hat x\in B_R$ be such that
\begin{equation*}\label{gamma_1_bound}
 B_r(\hat x)\subseteq \{\varrho_1<|x|<\varrho_2\},\qquad |u|\leqslant\gamma_1\text{ on $\overline { B_r(\hat x)}$}.
\end{equation*}
Then there exists $C=C(n,\gamma_1,\varrho_1,\varrho_2,r)$, whence independent of $\varepsilon\in(0,1]$ and $R> 0$, such that 
\begin{equation}\label{eq_ug_estimate}
 |Du(\hat x)|\leqslant C(n,\gamma_1,\varrho_1,\varrho_2,r).
\end{equation}

Let $S$ be the $t$-graph of $\langle x,y\rangle+u(x)$ in ${\mathbb{H}}^n$ over $B_R\times{\mathbb{R}}^n$. Since $u$ solves $\mathcal Q^\varepsilon u=0$, $H^\varepsilon\equiv 0$ by \eqref{espressionecurvaturamediariempergarficispeciali}. 

   \smallskip
   \noindent \textbf{Step 1.}
   Define $\varphi\in C^\infty(\overline{B_r(\hat x)})$ by 
   \begin{equation*}
 \varphi(x)\coloneqq u(\hat x)-1+
 \bigl(\gamma_1-u(\hat x)+1\bigr)\frac{|x-\hat x|^2}{r^2}.
\end{equation*}
By construction, $(u-\varphi)(\hat x)=1$ and $u-\varphi\leqslant 0$ on $\partial B_r(\hat x)$. Let $\gamma_2=\gamma_2(\gamma_1,r)> 0$ be such that
\begin{equation*}
    |\varphi|\leqslant \gamma_2,\qquad |D\varphi|\leqslant \gamma_2,\qquad \langle D^2\varphi\,v,v\rangle\leqslant\gamma_2|v|^2\text{ for any }v\in{\mathbb{R}}^n,\qquad \text{on }\overline{B_r(\hat x)}.
\end{equation*}
Fix $K> 0$ to be specified later, and set 
\begin{equation*}
 \eta(s)\coloneqq (e^{Ks}-1)e^{-K(\gamma_1+\gamma_2)},\qquad s\in{\mathbb{R}}.
\end{equation*}
By definition of $\gamma_1$ and $\gamma_2,$ then 
\begin{equation}\label{cosedieta3848685}
    0\leqslant \eta\big((u-\varphi)_+\big)\leqslant 1\quad\text{on }\overline{B_r(\hat x)},\qquad  \eta\big((u-\varphi)_+\big)=0\quad\text{on }\partial B_r(\hat x).
\end{equation}
Define
\begin{equation*}
 \Phi\coloneqq
     \eta((u-\varphi)_+)W_\varepsilon\quad\text{on }\overline{B_r(\hat x)},
 \qquad M\coloneqq \max_{\overline{B_r(\hat x)}}\Phi,
\end{equation*}
where $W_{\varepsilon}$ is defined in \eqref{eq:Weps}.
By \eqref{cosedieta3848685}, $\Phi=0$ on $\partial B_r(\hat x)$. Therefore, since $(u-\varphi)(\hat x)=1$, then $\Phi(\hat x)> 0$, the maximum $M$ is achieved at some $\bar x\in B_r(\hat x)$. In particular, $(u-\varphi)(\bar x)> 0$ at $\bar x$, whence $\Phi=
     \eta(u-\varphi)W_\varepsilon\text{ locally near }\bar x$.
Recalling the identification of \Cref{sec_tgraph}, define $\Psi\in C^\infty(S)$ by
\begin{equation*}
    \Psi(x,y)=\Psi(x)\coloneqq  \eta(u-\varphi)-MW_\varepsilon^{-1}.
\end{equation*}
By construction, for any $y\in{\mathbb{R}}^n$, $(\bar x,y)$ is a local maximum point of $\Psi$, whence
\begin{equation}\label{condizionimassimoinuge3485886}
    \nabla^{\varepsilon,S}\Psi(\bar x)=0,\qquad \Delta^{\varepsilon,S}\Psi(\bar x)\leqslant 0.
\end{equation}
Therefore, since
\begin{equation}\label{esprimereweconalpha38486848}
    W_\varepsilon^{-1}\overset{\eqref{normaleriemannianaepsilon},\eqref{normalipergraficiridotti38586}}{=}\frac{\alpha}{\sqrt{1+\varepsilon^2\alpha^2}},
\end{equation}
then, at $\bar x$,
\begin{equation}\label{laplacianouno384959649}
    \begin{split}
        0&\geqslant \Delta^{\varepsilon,S}\Psi\\
        &=\eta''(u-\varphi)|\nabla^{\varepsilon,S}(u-\varphi)|^2+\eta'(u-\varphi)\Delta^{\varepsilon,S}(u-\varphi)-M\Delta^{\varepsilon,S}\big(W_\varepsilon^{-1})\\
        \overset{\eqref{jacobitipeequation384969}}&{=}\eta''(u-\varphi)|\nabla^{\varepsilon,S}(u-\varphi)|^2+\eta'(u-\varphi)\Delta^{\varepsilon,S}(u-\varphi)+MW_\varepsilon^{-1}\Big(\left|h^\varepsilon\right|^2+\operatorname{Ric}^\varepsilon(\mathbf{N}^\varepsilon,\mathbf{N}^\varepsilon)\Big).
    \end{split}
\end{equation}
\textbf{Step 2.}
We claim (without intention to be sharp) that 
\begin{equation}\label{boundpermuniformeo48576884}
    M\leqslant M_0\coloneqq \sqrt{2+8\varrho_2^2+4\gamma_2^2}.
\end{equation}
Suppose not. We show that appropriate lower bounds in \eqref{laplacianouno384959649} and a suitable choice of $K$ lead to a contradiction. First, we bound the gradient term. Since $\eta\big((u-\varphi)(\bar x)\big)\leqslant 1$ by \eqref{cosedieta3848685} and $\Psi(\bar x)=0$ by construction, the choice of $\bar x$ yields $ M_0< M< W_\varepsilon$. Therefore
\begin{equation}\label{aux1uge3848697}
4|D(u-\varphi)|^2\geqslant 2|Du|^2-4|D\varphi|^2\geqslant
   |Du|^2+2+8\varrho_2^2+4\gamma_2^2-4|x|^2-\varepsilon^2-4|D\varphi|^2\geqslant |Du|^2\qquad\text{at }\bar x
\end{equation}
and
\begin{equation}\label{auxdueuge83496974}
      |Du|^2\geqslant 2+8\varrho_2^2+4\gamma_2^2-4|x|^2-\varepsilon^2\geqslant 4\varrho_2^2+1\geqslant 4|x|^2+\varepsilon^2\qquad\text{at }\bar x,
\end{equation}
whence, at $\bar x$,
\begin{equation}\label{sitmagradumenophiuge34869473}
    \begin{split}
        \left|\nabla^{\varepsilon,S}(u-\varphi)\right|^2\overset{\eqref{gradientesulgraficopercosenony38486}}&{=}\frac{(|Du|^2+4|x|^2+\varepsilon^2)|D(u-\varphi)|^2-\left\langle D(u-\varphi),Du\right\rangle^2}{W_\varepsilon^2}\\
        &\geqslant \left(\frac{4|x|^2+\varepsilon^2}{W_\varepsilon^2}\right)|D(u-\varphi)|^2\\
        \overset{\eqref{aux1uge3848697}}&{\geqslant}\left(\frac{|Du|^2}{W_\varepsilon^2}\right)\left(\frac{4|x|^2+\varepsilon^2}{4}\right)\\
        \overset{\eqref{auxdueuge83496974}}&{\geqslant}\frac{4|x|^2+\varepsilon^2}{8}\\
        &\geqslant \frac{\varrho_1^2}{2}.
    \end{split}
\end{equation}
\noindent \textbf{Step 3.} Next, we bound the second-order term. To this aim, observe that
\begin{equation*}
    g^{ij}_\varepsilon(x,y)\overset{\eqref{formaspecialecoso2939469}}{=}\delta_{ij}-\frac{u_i(x)u_j(x)}{W_\varepsilon(x)^2}=W_\varepsilon(x)^{-2}A^\varepsilon_{ij}(x,Du(x)),\qquad i,j=1,\ldots, n.
\end{equation*}
Therefore, since $\mathcal Q^\varepsilon u=0$, 
\begin{equation*}
        \Delta^{\varepsilon,S}u\overset{\eqref{equazioneperlaplacianograficoridotto38486854}}{=}\frac{1}{W_\varepsilon^2}\sum_{i,j=1}^{n}A^\varepsilon_{ij} D^2u_{ij}+\frac{4\left\langle Du,x\right\rangle}{W_\varepsilon^2}=\frac{8\left\langle Du,x\right\rangle}{W_\varepsilon^2}\geqslant -2.
\end{equation*}
Moreover, by definition of $\gamma_2$,
\begin{equation*}
    \Delta^{\varepsilon,S}\varphi \overset{\eqref{equazioneperlaplacianograficoridotto38486854}}{=}\Delta\varphi-\frac{\left\langle D^2 \varphi\,Du,Du\right\rangle}{W_\varepsilon^2}+\frac{4\left\langle D\varphi,x\right\rangle}{W_\varepsilon^2}\leqslant (n+1)\gamma_2+\frac{\gamma_2}{|x|}\leqslant (n+1)\gamma_2+\frac{\gamma_2}{\varrho_1}.
\end{equation*}
Therefore,
\begin{equation}\label{stimalapluge3784869847374}
    \Delta^{\varepsilon,S}(u-\varphi)\geqslant -2-\left(n+1+\frac{1}{\varrho_1}\right)\gamma_2.
    \end{equation}
    \noindent \textbf{Step 4.} Finally, we bound the curvature term. Notice that $S$ is non-characteristic over $\{\varrho_1< |x|< \varrho_2\}\times{\mathbb{R}}^n$. The following quantities are tacitly evaluated at $\bar x$. Since
    \begin{equation}\label{chainrulealphawe3885764}
    \alpha W_\varepsilon J(\nu)\left(W_\varepsilon^{-1}\right)\overset{\eqref{esprimereweconalpha38486848}}{=}\frac{J(\nu)\alpha}{1+\varepsilon^2\alpha^2},
    \end{equation}
    we discard the non-negative terms in \eqref{riemcurvaturetermspresoda3949596}, obtaining 
    \begin{equation*}
        MW_\varepsilon^{-1}\Big(\left|h^\varepsilon\right|^2+\operatorname{Ric}^\varepsilon(\mathbf{N}^\varepsilon,\mathbf{N}^\varepsilon)\Big)\geqslant 4MW_\varepsilon^{-1}\left(\frac{J(\nu)\alpha}{1+\varepsilon^2\alpha^2}\right)\overset{\eqref{chainrulealphawe3885764}}{=}4M\alpha J(\nu)\left(W_\varepsilon^{-1}\right).
    \end{equation*}
    Noticing that 
    \begin{equation*}
        0\overset{\eqref{condizionimassimoinuge3485886}}{=}J(\nu)\Psi=\eta'(u-\varphi)J(\nu)(u-\varphi)-MJ(\nu)\left(W_\varepsilon^{-1}\right),
    \end{equation*}
    then 
    \begin{equation*}
